python3 - <<'PY'
import ast, subprocess, pathlib, re, collections
files = [f for f in subprocess.run(["git","ls-files","*.py"],capture_output=True,text=True).stdout.split()
         if not f.startswith("alembic/")]
srcs = {f: pathlib.Path(f).read_text() for f in files}
allsrc = "\n".join(srcs.values())
defs = []
for f, src in srcs.items():
    if f.startswith("tests/"): continue
    tree = ast.parse(src)
    for node in tree.body:
        if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
            defs.append((f,node.lineno,node.name))
        elif isinstance(node,ast.Assign):
            for t in node.targets:
                if isinstance(t,ast.Name) and t.id.isupper():
                    defs.append((f,node.lineno,t.id))
for f,ln,name in defs:
    n = len(re.findall(r'\b'+re.escape(name)+r'\b', allsrc))
    if n <= 1:
        print(f"UNUSED? {f}:{ln} {name}")
PY
